import{_ as d,a0 as l,w as o,s as p,I as t,x as e,a1 as i,A as n,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"怎样用 Bash 编程：逻辑操作符和 shell 扩展 | LCTT x X-CMD","titleTemplate":false,"description":"怎样用 Bash 编程：逻辑操作符和 shell 扩展 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎样用 Bash 编程：逻辑操作符和 shell 扩展 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎样用 Bash 编程：逻辑操作符和 shell 扩展 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191022 How to program with Bash- Logical operators and shell expansions","title":"怎样用 Bash 编程：逻辑操作符和 shell 扩展","tag":"201912","desc":""},"relativePath":"201912/20191022 How to program with Bash- Logical operators and shell expansions.md","filePath":"[post].md"}'),c={name:"201912/20191022 How to program with Bash- Logical operators and shell expansions.md"};function h(u,s,g,k,b,f){const a=l("Link");return o(),p("div",null,[s[26]||(s[26]=t("h1",{id:"怎样用-bash-编程-逻辑操作符和-shell-扩展",tabindex:"-1"},[e("怎样用 Bash 编程：逻辑操作符和 shell 扩展 "),t("a",{class:"header-anchor",href:"#怎样用-bash-编程-逻辑操作符和-shell-扩展","aria-label":"Permalink to “怎样用 Bash 编程：逻辑操作符和 shell 扩展”"},"​")],-1)),s[27]||(s[27]=t("blockquote",null,[t("p",null,"学习逻辑操作符和 shell 扩展，本文是三篇 Bash 编程系列的第二篇。")],-1)),s[28]||(s[28]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/201912/17/173459pxhz0aiicimzd1m2.jpg",alt:""})],-1)),t("p",null,[s[1]||(s[1]=e("Bash 是一种强大的编程语言，完美契合命令行和 shell 脚本。本系列（三篇文章，基于我的 ",-1)),i(a,{href:"http://www.both.org/?page_id=1183"},{default:n(()=>[...s[0]||(s[0]=[e("三集 Linux 自学课程",-1)])]),_:1}),s[2]||(s[2]=e("）讲解如何在 CLI 使用 Bash 编程。",-1))]),t("p",null,[i(a,{href:"https://linux.cn/article-11552-1.html"},{default:n(()=>[...s[3]||(s[3]=[e("第一篇文章",-1)])]),_:1}),s[4]||(s[4]=e(" 讲解了 Bash 的一些简单命令行操作，包括如何使用变量和控制操作符。第二篇文章探讨文件、字符串、数字等类型和各种各样在执行流中提供控制逻辑的的逻辑运算符，还有 Bash 中的各类 shell 扩展。本系列第三篇也是最后一篇文章，将会探索能重复执行操作的 ",-1)),s[5]||(s[5]=t("code",null,"for",-1)),s[6]||(s[6]=e(" 、",-1)),s[7]||(s[7]=t("code",null,"while",-1)),s[8]||(s[8]=e(" 和 ",-1)),s[9]||(s[9]=t("code",null,"until",-1)),s[10]||(s[10]=e(" 循环。",-1))]),s[29]||(s[29]=r(`<p>逻辑操作符是程序中进行判断的根本要素，也是执行不同的语句组合的依据。有时这也被称为流控制。</p><h3 id="逻辑操作符" tabindex="-1">逻辑操作符 <a class="header-anchor" href="#逻辑操作符" aria-label="Permalink to “逻辑操作符”">​</a></h3><p>Bash 中有大量的用于不同条件表达式的逻辑操作符。最基本的是 <code>if</code> 控制结构，它判断一个条件，如果条件为真，就执行一些程序语句。操作符共有三类：文件、数字和非数字操作符。如果条件为真，所有的操作符返回真值（<code>0</code>），如果条件为假，返回假值（<code>1</code>）。</p><p>这些比较操作符的函数语法是，一个操作符加一个或两个参数放在中括号内，后面跟一系列程序语句，如果条件为真，程序语句执行，可能会有另一个程序语句列表，该列表在条件为假时执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if [ arg1 operator arg2 ] ; then list</span></span>
<span class="line"><span>或</span></span>
<span class="line"><span>if [ arg1 operator arg2 ] ; then list ; else list ; fi</span></span></code></pre></div><p>像例子中那样，在比较表达式中，空格不能省略。中括号的每部分，<code>[</code> 和 <code>]</code>，是跟 <code>test</code> 命令一样的传统的 Bash 符号：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if test arg1 operator arg2 ; then list</span></span></code></pre></div><p>还有一个更新的语法能提供一点点便利，一些系统管理员比较喜欢用。这种格式对于不同版本的 Bash 和一些 shell 如 ksh（Korn shell）兼容性稍差。格式如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if [[ arg1 operator arg2 ]] ; then list</span></span></code></pre></div><h4 id="文件操作符" tabindex="-1">文件操作符 <a class="header-anchor" href="#文件操作符" aria-label="Permalink to “文件操作符”">​</a></h4><p>文件操作符是 Bash 中一系列强大的逻辑操作符。图表 1 列出了 20 多种不同的 Bash 处理文件的操作符。在我的脚本中使用频率很高。</p><div class="table-wrap"><table><thead><tr><th>操作符</th><th>描述</th></tr></thead><tbody><tr><td><code>-a filename</code></td><td>如果文件存在，返回真值；文件可以为空也可以有内容，但是只要它存在，就返回真值</td></tr><tr><td><code>-b filename</code></td><td>如果文件存在且是一个块设备，如 <code>/dev/sda</code> 或 <code>/dev/sda1</code>，则返回真值</td></tr><tr><td><code>-c filename</code></td><td>如果文件存在且是一个字符设备，如 <code>/dev/TTY1</code>，则返回真值</td></tr><tr><td><code>-d filename</code></td><td>如果文件存在且是一个目录，返回真值</td></tr><tr><td><code>-e filename</code></td><td>如果文件存在，返回真值；与上面的 <code>-a</code> 相同</td></tr><tr><td><code>-f filename</code></td><td>如果文件存在且是一个一般文件，不是目录、设备文件或链接等的其他的文件，则返回 真值</td></tr><tr><td><code>-g filename</code></td><td>如果文件存在且 <code>SETGID</code> 标记被设置在其上，返回真值</td></tr><tr><td><code>-h filename</code></td><td>如果文件存在且是一个符号链接，则返回真值</td></tr><tr><td><code>-k filename</code></td><td>如果文件存在且粘滞位已设置，则返回真值</td></tr><tr><td><code>-p filename</code></td><td>如果文件存在且是一个命名的管道（FIFO），返回真值</td></tr><tr><td><code>-r filename</code></td><td>如果文件存在且有可读权限（它的可读位被设置），返回真值</td></tr><tr><td><code>-s filename</code></td><td>如果文件存在且大小大于 0，返回真值；如果一个文件存在但大小为 0，则返回假值</td></tr><tr><td><code>-t fd</code></td><td>如果文件描述符 <code>fd</code> 被打开且被关联到一个终端设备上，返回真值</td></tr><tr><td><code>-u filename</code></td><td>如果文件存在且它的 <code>SETUID</code> 位被设置，返回真值</td></tr><tr><td><code>-w filename</code></td><td>如果文件存在且有可写权限，返回真值</td></tr><tr><td><code>-x filename</code></td><td>如果文件存在且有可执行权限，返回真值</td></tr><tr><td><code>-G filename</code></td><td>如果文件存在且文件的组 ID 与当前用户相同，返回真值</td></tr><tr><td><code>-L filename</code></td><td>如果文件存在且是一个符号链接，返回真值（同 <code>-h</code>）</td></tr><tr><td><code>-N filename</code></td><td>如果文件存在且从文件上一次被读取后文件被修改过，返回真值</td></tr><tr><td><code>-O filename</code></td><td>如果文件存在且你是文件的拥有者，返回真值</td></tr><tr><td><code>-S filename</code></td><td>如果文件存在且文件是套接字，返回真值</td></tr><tr><td><code>file1 -ef file2</code></td><td>如果文件 <code>file1</code> 和文件 <code>file2</code> 指向同一设备的同一 INODE 号，返回真值（即硬链接）</td></tr><tr><td><code>file1 -nt file2</code></td><td>如果文件 <code>file1</code> 比 <code>file2</code> 新（根据修改日期），或 <code>file1</code> 存在而 <code>file2</code> 不存在，返回真值</td></tr><tr><td><code>file1 -ot file2</code></td><td>如果文件 <code>file1</code> 比 <code>file2</code> 旧（根据修改日期），或 <code>file1</code> 不存在而 <code>file2</code> 存在</td></tr></tbody></table></div><p><em>图表 1：Bash 文件操作符</em></p><p>以测试一个文件存在与否来举例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ File=&quot;TestFile1&quot; ; if [ -e $File ] ; then echo &quot;The file $File exists.&quot; ; else echo &quot;The file $File does not exist.&quot; ; fi</span></span>
<span class="line"><span>The file TestFile1 does not exist.</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>创建一个用来测试的文件，命名为 <code>TestFile1</code>。目前它不需要包含任何数据：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ touch TestFile1</span></span></code></pre></div><p>在这个简短的 CLI 程序中，修改 <code>$File</code> 变量的值相比于在多个地方修改表示文件名的字符串的值要容易：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ File=&quot;TestFile1&quot; ; if [ -e $File ] ; then echo &quot;The file $File exists.&quot; ; else echo &quot;The file $File does not exist.&quot; ; fi</span></span>
<span class="line"><span>The file TestFile1 exists.</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>现在，运行一个测试来判断一个文件是否存在且长度不为 0（表示它包含数据）。假设你想判断三种情况：</p><ol><li>文件不存在；</li><li>文件存在且为空；</li><li>文件存在且包含数据。</li></ol><p>因此，你需要一组更复杂的测试代码 — 为了测试所有的情况，使用 <code>if-elif-else</code> 结构中的 <code>elif</code> 语句：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ File=&quot;TestFile1&quot; ; if [ -s $File ] ; then echo &quot;$File exists and contains data.&quot; ; fi</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>在这个情况中，文件存在但不包含任何数据。向文件添加一些数据再运行一次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ File=&quot;TestFile1&quot; ; echo &quot;This is file $File&quot; &gt; $File ; if [ -s $File ] ; then echo &quot;$File exists and contains data.&quot; ; fi</span></span>
<span class="line"><span>TestFile1 exists and contains data.</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>这组语句能返回正常的结果，但是仅仅是在我们已知三种可能的情况下测试某种确切的条件。添加一段 <code>else</code> 语句，这样你就可以更精确地测试。把文件删掉，你就可以完整地测试这段新代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ File=&quot;TestFile1&quot; ; rm $File ; if [ -s $File ] ; then echo &quot;$File exists and contains data.&quot; ; else echo &quot;$File does not exist or is empty.&quot; ; fi</span></span>
<span class="line"><span>TestFile1 does not exist or is empty.</span></span></code></pre></div><p>现在创建一个空文件用来测试：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ File=&quot;TestFile1&quot; ; touch $File ; if [ -s $File ] ; then echo &quot;$File exists and contains data.&quot; ; else echo &quot;$File does not exist or is empty.&quot; ; fi</span></span>
<span class="line"><span>TestFile1 does not exist or is empty.</span></span></code></pre></div><p>向文件添加一些内容，然后再测试一次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ File=&quot;TestFile1&quot; ; echo &quot;This is file $File&quot; &gt; $File ; if [ -s $File ] ; then echo &quot;$File exists and contains data.&quot; ; else echo &quot;$File does not exist or is empty.&quot; ; fi</span></span>
<span class="line"><span>TestFile1 exists and contains data.</span></span></code></pre></div><p>现在加入 <code>elif</code> 语句来辨别是文件不存在还是文件为空：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ File=&quot;TestFile1&quot; ; touch $File ; if [ -s $File ] ; then echo &quot;$File exists and contains data.&quot; ; elif [ -e $File ] ; then echo &quot;$File exists and is empty.&quot; ; else echo &quot;$File does not exist.&quot; ; fi</span></span>
<span class="line"><span>TestFile1 exists and is empty.</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ File=&quot;TestFile1&quot; ; echo &quot;This is $File&quot; &gt; $File ; if [ -s $File ] ; then echo &quot;$File exists and contains data.&quot; ; elif [ -e $File ] ; then echo &quot;$File exists and is empty.&quot; ; else echo &quot;$File does not exist.&quot; ; fi</span></span>
<span class="line"><span>TestFile1 exists and contains data.</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>现在你有一个可以测试这三种情况的 Bash CLI 程序，但是可能的情况是无限的。</p><p>如果你能像保存在文件中的脚本那样组织程序语句，那么即使对于更复杂的命令组合也会很容易看出它们的逻辑结构。图表 2 就是一个示例。 <code>if-elif-else</code> 结构中每一部分的程序语句的缩进让逻辑更变得清晰。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>File=&quot;TestFile1&quot;</span></span>
<span class="line"><span>echo &quot;This is $File&quot; &gt; $File</span></span>
<span class="line"><span>if [ -s $File ]</span></span>
<span class="line"><span>   then</span></span>
<span class="line"><span>   echo &quot;$File exists and contains data.&quot;</span></span>
<span class="line"><span>elif [ -e $File ]</span></span>
<span class="line"><span>   then</span></span>
<span class="line"><span>   echo &quot;$File exists and is empty.&quot;</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>   echo &quot;$File does not exist.&quot;</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p><em>图表 2: 像在脚本里一样重写书写命令行程序</em></p><p>对于大多数 CLI 程序来说，让这些复杂的命令变得有逻辑需要写很长的代码。虽然 CLI 可能是用 Linux 或 Bash 内置的命令，但是当 CLI 程序很长或很复杂时，创建一个保存在文件中的脚本将更有效，保存到文件中后，可以随时运行。</p><h4 id="字符串比较操作符" tabindex="-1">字符串比较操作符 <a class="header-anchor" href="#字符串比较操作符" aria-label="Permalink to “字符串比较操作符”">​</a></h4><p>字符串比较操作符使我们可以对字符串中的字符按字母顺序进行比较。图表 3 列出了仅有的几个字符串比较操作符。</p><div class="table-wrap"><table><thead><tr><th>操作符</th><th>描述</th></tr></thead><tbody><tr><td><code>-z string</code></td><td>如果字符串的长度为 0 ，返回真值</td></tr><tr><td><code>-n string</code></td><td>如果字符串的长度不为 0 ，返回真值</td></tr><tr><td><code>string1 == string2</code> 或 <code>string1 = string2</code></td><td>如果两个字符串相等，返回真值。处于遵从 POSIX 一致性，在测试命令中应使用一个等号 <code>=</code>。与命令 <code>[[</code> 一起使用时，会进行如上描述的模式匹配（混合命令）。</td></tr><tr><td><code>string1 != string2</code></td><td>两个字符串不相等，返回真值</td></tr><tr><td><code>string1 &lt; string2</code></td><td>如果对 <code>string1</code> 和 <code>string2</code> 按字母顺序进行排序，<code>string1</code> 排在 <code>string2</code> 前面（即基于地区设定的对所有字母和特殊字符的排列顺序）</td></tr><tr><td><code>string1 &gt; string2</code></td><td>如果对 <code>string1</code> 和 <code>string2</code> 按字母顺序进行排序，<code>string1</code> 排在 <code>string2</code> 后面</td></tr></tbody></table></div><p><em>图表 3: Bash 字符串逻辑操作符</em></p><p>首先，检查字符串长度。比较表达式中 <code>$MyVar</code> 两边的双引号不能省略（你仍应该在目录 <code>~/testdir</code> 下 ）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ MyVar=&quot;&quot; ; if [ -z &quot;&quot; ] ; then echo &quot;MyVar is zero length.&quot; ; else echo &quot;MyVar contains data&quot; ; fi</span></span>
<span class="line"><span>MyVar is zero length.</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ MyVar=&quot;Random text&quot; ; if [ -z &quot;&quot; ] ; then echo &quot;MyVar is zero length.&quot; ; else echo &quot;MyVar contains data&quot; ; fi</span></span>
<span class="line"><span>MyVar is zero length.</span></span></code></pre></div><p>你也可以这样做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ MyVar=&quot;Random text&quot; ; if [ -n &quot;$MyVar&quot; ] ; then echo &quot;MyVar contains data.&quot; ; else echo &quot;MyVar is zero length&quot; ; fi</span></span>
<span class="line"><span>MyVar contains data.</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ MyVar=&quot;&quot; ; if [ -n &quot;$MyVar&quot; ] ; then echo &quot;MyVar contains data.&quot; ; else echo &quot;MyVar is zero length&quot; ; fi</span></span>
<span class="line"><span>MyVar is zero length</span></span></code></pre></div><p>有时候你需要知道一个字符串确切的长度。这虽然不是比较，但是也与比较相关。不幸的是，计算字符串的长度没有简单的方法。有很多种方法可以计算，但是我认为使用 <code>expr</code>（求值表达式）命令是相对最简单的一种。阅读 <code>expr</code> 的手册页可以了解更多相关知识。注意表达式中你检测的字符串或变量两边的引号不要省略。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ MyVar=&quot;&quot; ; expr length &quot;$MyVar&quot;</span></span>
<span class="line"><span>0</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ MyVar=&quot;How long is this?&quot; ; expr length &quot;$MyVar&quot;</span></span>
<span class="line"><span>17</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ expr length &quot;We can also find the length of a literal string as well as a variable.&quot;</span></span>
<span class="line"><span>70</span></span></code></pre></div><p>关于比较操作符，在我们的脚本中使用了大量的检测两个字符串是否相等（例如，两个字符串是否实际上是同一个字符串）的操作。我使用的是非 POSIX 版本的比较表达式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ Var1=&quot;Hello World&quot; ; Var2=&quot;Hello World&quot; ; if [ &quot;$Var1&quot; == &quot;$Var2&quot; ] ; then echo &quot;Var1 matches Var2&quot; ; else echo &quot;Var1 and Var2 do not match.&quot; ; fi</span></span>
<span class="line"><span>Var1 matches Var2</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ Var1=&quot;Hello World&quot; ; Var2=&quot;Hello world&quot; ; if [ &quot;$Var1&quot; == &quot;$Var2&quot; ] ; then echo &quot;Var1 matches Var2&quot; ; else echo &quot;Var1 and Var2 do not match.&quot; ; fi</span></span>
<span class="line"><span>Var1 and Var2 do not match.</span></span></code></pre></div><p>在你自己的脚本中去试一下这些操作符。</p><h4 id="数字比较操作符" tabindex="-1">数字比较操作符 <a class="header-anchor" href="#数字比较操作符" aria-label="Permalink to “数字比较操作符”">​</a></h4><p>数字操作符用于两个数字参数之间的比较。像其他类操作符一样，大部分都很容易理解。</p><div class="table-wrap"><table><thead><tr><th>操作符</th><th>描述</th></tr></thead><tbody><tr><td><code>arg1 -eq arg2</code></td><td>如果 <code>arg1</code> 等于 <code>arg2</code>，返回真值</td></tr><tr><td><code>arg1 -ne arg2</code></td><td>如果 <code>arg1</code> 不等于 <code>arg2</code>，返回真值</td></tr><tr><td><code>arg1 -lt arg2</code></td><td>如果 <code>arg1</code> 小于 <code>arg2</code>，返回真值</td></tr><tr><td><code>arg1 -le arg2</code></td><td>如果 <code>arg1</code> 小于或等于 <code>arg2</code>，返回真值</td></tr><tr><td><code>arg1 -gt arg2</code></td><td>如果 <code>arg1</code> 大于 <code>arg2</code>，返回真值</td></tr><tr><td><code>arg1 -ge arg2</code></td><td>如果 <code>arg1</code> 大于或等于 <code>arg2</code>，返回真值</td></tr></tbody></table></div><p><em>图表 4: Bash 数字比较逻辑操作符</em></p><p>来看几个简单的例子。第一个示例设置变量 <code>$X</code> 的值为 1，然后检测 <code>$X</code> 是否等于 1。第二个示例中，<code>$X</code> 被设置为 0，所以比较表达式返回结果不为真值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ X=1 ; if [ $X -eq 1 ] ; then echo &quot;X equals 1&quot; ; else echo &quot;X does not equal 1&quot; ; fi</span></span>
<span class="line"><span>X equals 1</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ X=0 ; if [ $X -eq 1 ] ; then echo &quot;X equals 1&quot; ; else echo &quot;X does not equal 1&quot; ; fi</span></span>
<span class="line"><span>X does not equal 1</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>自己来多尝试一下其他的。</p><h4 id="杂项操作符" tabindex="-1">杂项操作符 <a class="header-anchor" href="#杂项操作符" aria-label="Permalink to “杂项操作符”">​</a></h4><p>这些杂项操作符展示一个 shell 选项是否被设置，或一个 shell 变量是否有值，但是它不显示变量的值，只显示它是否有值。</p><div class="table-wrap"><table><thead><tr><th>操作符</th><th>描述</th></tr></thead><tbody><tr><td><code>-o optname</code></td><td>如果一个 shell 选项 <code>optname</code> 是启用的（查看内建在 Bash 手册页中的 set <code>-o</code> 选项描述下面的选项列表），则返回真值</td></tr><tr><td><code>-v varname</code></td><td>如果 shell 变量 <code>varname</code> 被设置了值（被赋予了值），则返回真值</td></tr><tr><td><code>-R varname</code></td><td>如果一个 shell 变量 <code>varname</code> 被设置了值且是一个名字引用，则返回真值</td></tr></tbody></table></div><p><em>图表 5: 杂项 Bash 逻辑操作符</em></p><p>自己来使用这些操作符实践下。</p><h3 id="扩展" tabindex="-1">扩展 <a class="header-anchor" href="#扩展" aria-label="Permalink to “扩展”">​</a></h3><p>Bash 支持非常有用的几种类型的扩展和命令替换。根据 Bash 手册页，Bash 有七种扩展格式。本文只介绍其中五种：<code>~</code> 扩展、算术扩展、路径名称扩展、大括号扩展和命令替换。</p><h4 id="大括号扩展" tabindex="-1">大括号扩展 <a class="header-anchor" href="#大括号扩展" aria-label="Permalink to “大括号扩展”">​</a></h4><p>大括号扩展是生成任意字符串的一种方法。（下面的例子是用特定模式的字符创建大量的文件。）大括号扩展可以用于产生任意字符串的列表，并把它们插入一个用静态字符串包围的特定位置或静态字符串的两端。这可能不太好想象，所以还是来实践一下。</p><p>首先，看一下大括号扩展的作用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ echo {string1,string2,string3}</span></span>
<span class="line"><span>string1 string2 string3</span></span></code></pre></div><p>看起来不是很有用，对吧？但是用其他方式使用它，再来看看：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ echo &quot;Hello &quot;{David,Jen,Rikki,Jason}.</span></span>
<span class="line"><span>Hello David. Hello Jen. Hello Rikki. Hello Jason.</span></span></code></pre></div><p>这看起来貌似有点用了 — 我们可以少打很多字。现在试一下这个：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ echo b{ed,olt,ar}s</span></span>
<span class="line"><span>beds bolts bars</span></span></code></pre></div><p>我可以继续举例，但是你应该已经理解了它的用处。</p><h4 id="扩展-1" tabindex="-1">~ 扩展 <a class="header-anchor" href="#扩展-1" aria-label="Permalink to “~ 扩展”">​</a></h4><p>资料显示，使用最多的扩展是波浪字符（<code>~</code>）扩展。当你在命令中使用它（如 <code>cd ~/Documents</code>）时，Bash shell 把这个快捷方式展开成用户的完整的家目录。</p><p>使用这个 Bash 程序观察 <code>~</code> 扩展的作用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ echo ~</span></span>
<span class="line"><span>/home/student</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ echo ~/Documents</span></span>
<span class="line"><span>/home/student/Documents</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ Var1=~/Documents ; echo $Var1 ; cd $Var1</span></span>
<span class="line"><span>/home/student/Documents</span></span>
<span class="line"><span>[student@studentvm1 Documents]$</span></span></code></pre></div><h4 id="路径名称扩展" tabindex="-1">路径名称扩展 <a class="header-anchor" href="#路径名称扩展" aria-label="Permalink to “路径名称扩展”">​</a></h4><p>路径名称扩展是展开文件通配模式为匹配该模式的完整路径名称的另一种说法，匹配字符使用 <code>?</code> 和 <code>*</code>。文件通配指的是在大量操作中匹配文件名、路径和其他字符串时用特定的模式字符产生极大的灵活性。这些特定的模式字符允许匹配字符串中的一个、多个或特定字符。</p><ul><li><code>?</code> — 匹配字符串中特定位置的一个任意字符</li><li><code>*</code> — 匹配字符串中特定位置的 0 个或多个任意字符</li></ul><p>这个扩展用于匹配路径名称。为了弄清它的用法，请确保 <code>testdir</code> 是当前工作目录（<code>PWD</code>），先执行基本的列出清单命令 <code>ls</code>（我家目录下的内容跟你的不一样）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ ls</span></span>
<span class="line"><span>chapter6  cpuHog.dos    dmesg1.txt  Documents  Music       softlink1  testdir6    Videos</span></span>
<span class="line"><span>chapter7  cpuHog.Linux  dmesg2.txt  Downloads  Pictures    Templates  testdir</span></span>
<span class="line"><span>testdir  cpuHog.mac    dmesg3.txt  file005    Public      testdir    tmp</span></span>
<span class="line"><span>cpuHog     Desktop       dmesg.txt   link3      random.txt  testdir1   umask.test</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>现在列出以 <code>Do</code>、<code>testdir/Documents</code> 和 <code>testdir/Downloads</code> 开头的目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Documents:</span></span>
<span class="line"><span>Directory01  file07  file15        test02  test10  test20      testfile13  TextFiles</span></span>
<span class="line"><span>Directory02  file08  file16        test03  test11  testfile01  testfile14</span></span>
<span class="line"><span>file01       file09  file17        test04  test12  testfile04  testfile15</span></span>
<span class="line"><span>file02       file10  file18        test05  test13  testfile05  testfile16</span></span>
<span class="line"><span>file03       file11  file19        test06  test14  testfile09  testfile17</span></span>
<span class="line"><span>file04       file12  file20        test07  test15  testfile10  testfile18</span></span>
<span class="line"><span>file05       file13  Student1.txt  test08  test16  testfile11  testfile19</span></span>
<span class="line"><span>file06       file14  test01        test09  test18  testfile12  testfile20</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Downloads:</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>然而，并没有得到你期望的结果。它列出了以 <code>Do</code> 开头的目录下的内容。使用 <code>-d</code> 选项，仅列出目录而不列出它们的内容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ ls -d Do*</span></span>
<span class="line"><span>Documents  Downloads</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>在两个例子中，Bash shell 都把 <code>Do*</code> 模式展开成了匹配该模式的目录名称。但是如果有文件也匹配这个模式，会发生什么？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ touch Downtown ; ls -d Do*</span></span>
<span class="line"><span>Documents  Downloads  Downtown</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>因此所有匹配这个模式的文件也被展开成了完整名字。</p><h4 id="命令替换" tabindex="-1">命令替换 <a class="header-anchor" href="#命令替换" aria-label="Permalink to “命令替换”">​</a></h4><p>命令替换是让一个命令的标准输出数据流被当做参数传给另一个命令的扩展形式，例如，在一个循环中作为一系列被处理的项目。Bash 手册页显示：“命令替换可以让你用一个命令的输出替换为命令的名字。”这可能不太好理解。</p><p>命令替换有两种格式：\`command\` 和 <code>$(command)</code>。在更早的格式中使用反引号（\`），在命令中使用反斜杠（<code>\\</code>）来保持它转义之前的文本含义。然而，当用在新版本的括号格式中时，反斜杠被当做一个特殊字符处理。也请注意带括号的格式打开个关闭命令语句都是用一个括号。</p><p>我经常在命令行程序和脚本中使用这种能力，一个命令的结果能被用作另一个命令的参数。</p><p>来看一个非常简单的示例，这个示例使用了这个扩展的两种格式（再一次提醒，确保 <code>testdir</code> 是当前工作目录）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ echo &quot;Todays date is \`date\`&quot;</span></span>
<span class="line"><span>Todays date is Sun Apr  7 14:42:46 EDT 2019</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ echo &quot;Todays date is $(date)&quot;</span></span>
<span class="line"><span>Todays date is Sun Apr  7 14:42:59 EDT 2019</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p><code>-seq</code> 工具用于一个数字序列：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ seq 5</span></span>
<span class="line"><span>1</span></span>
<span class="line"><span>2</span></span>
<span class="line"><span>3</span></span>
<span class="line"><span>4</span></span>
<span class="line"><span>5</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ echo \`seq 5\`</span></span>
<span class="line"><span>1 2 3 4 5</span></span>
<span class="line"><span>[student@studentvm1 testdir]$</span></span></code></pre></div><p>现在你可以做一些更有用处的操作，比如创建大量用于测试的空文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ for I in $(seq -w 5000) ; do touch file-$I ; done</span></span></code></pre></div><p><code>seq</code> 工具加上 <code>-w</code> 选项后，在生成的数字前面会用 0 补全，这样所有的结果都等宽，例如，忽略数字的值，它们的位数一样。这样在对它们按数字顺序进行排列时很容易。</p><p><code>seq -w 5000</code> 语句生成了 1 到 5000 的数字序列。通过把命令替换用于 <code>for</code> 语句，<code>for</code> 语句就可以使用该数字序列来生成文件名的数字部分。</p><h4 id="算术扩展" tabindex="-1">算术扩展 <a class="header-anchor" href="#算术扩展" aria-label="Permalink to “算术扩展”">​</a></h4><p>Bash 可以进行整型的数学计算，但是比较繁琐（你一会儿将看到）。数字扩展的语法是 <code>$((arithmetic-expression))</code> ，分别用两个括号来打开和关闭表达式。算术扩展在 shell 程序或脚本中类似命令替换；表达式结算后的结果替换了表达式，用于 shell 后续的计算。</p><p>我们再用一个简单的用法来开始：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ echo $((1+1))</span></span>
<span class="line"><span>2</span></span>
<span class="line"><span>[student@studentvm1 testdir]$ Var1=5 ; Var2=7 ; Var3=$((Var1*Var2)) ; echo &quot;Var 3 = $Var3&quot;</span></span>
<span class="line"><span>Var 3 = 35</span></span></code></pre></div><p>下面的除法结果是 0，因为表达式的结果是一个小于 1 的整型数字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ Var1=5 ; Var2=7 ; Var3=$((Var1/Var2)) ; echo &quot;Var 3 = $Var3&quot;</span></span>
<span class="line"><span>Var 3 = 0</span></span></code></pre></div><p>这是一个我经常在脚本或 CLI 程序中使用的一个简单的计算，用来查看在 Linux 主机中使用了多少虚拟内存。 <code>free</code> 不提供我需要的数据：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[student@studentvm1 testdir]$ RAM=\`free | grep ^Mem | awk &#39;{print $2}&#39;\` ; Swap=\`free | grep ^Swap | awk &#39;{print $2}&#39;\` ; echo &quot;RAM = $RAM and Swap = $Swap&quot; ; echo &quot;Total Virtual memory is $((RAM+Swap))&quot; ;</span></span>
<span class="line"><span>RAM = 4037080 and Swap = 6291452</span></span>
<span class="line"><span>Total Virtual memory is 10328532</span></span></code></pre></div><p>我使用 \` 字符来划定用作命令替换的界限。</p><p>我用 Bash 算术扩展的场景主要是用脚本检查系统资源用量后基于返回的结果选择一个程序运行的路径。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>本文是 Bash 编程语言系列的第二篇，探讨了 Bash 中文件、字符串、数字和各种提供流程控制逻辑的逻辑操作符还有不同种类的 shell 扩展。</p><hr>`,115)),t("p",null,[s[12]||(s[12]=e("via: ",-1)),i(a,{href:"https://opensource.com/article/19/10/programming-bash-logical-operators-shell-expansions"},{default:n(()=>[...s[11]||(s[11]=[e("https://opensource.com/article/19/10/programming-bash-logical-operators-shell-expansions",-1)])]),_:1})]),t("p",null,[s[17]||(s[17]=e("作者：",-1)),i(a,{href:"https://opensource.com/users/dboth"},{default:n(()=>[...s[13]||(s[13]=[e("David Both",-1)])]),_:1}),s[18]||(s[18]=e(" 选题：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[14]||(s[14]=[e("lujun9972",-1)])]),_:1}),s[19]||(s[19]=e(" 译者：",-1)),i(a,{href:"https://github.com/lxbwolf"},{default:n(()=>[...s[15]||(s[15]=[e("lxbwolf",-1)])]),_:1}),s[20]||(s[20]=e(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[16]||(s[16]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[23]||(s[23]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[21]||(s[21]=[e("LCTT",-1)])]),_:1}),s[24]||(s[24]=e(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...s[22]||(s[22]=[e("Linux中国",-1)])]),_:1}),s[25]||(s[25]=e(" 荣誉推出",-1))])])}const v=d(c,[["render",h]]);export{y as __pageData,v as default};
